-- ====================================================================
-- VocabFlow - Seed Data: 7 Categories & 330 Vocabulary Words
-- Run this in Supabase SQL Editor to populate words database
-- ====================================================================

-- 1. Insert Categories
on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  icon = excluded.icon,
  color = excluded.color;

-- 2. Insert Words (330 items)
on conflict (id) do update set
  word = excluded.word,
  translation_ru = excluded.translation_ru,
  translation_kz = excluded.translation_kz,
  definition = excluded.definition,
  example = excluded.example,
  pronunciation = excluded.pronunciation,
  part_of_speech = excluded.part_of_speech,
  level = excluded.level,
  category_id = excluded.category_id,
  synonyms = excluded.synonyms,
  antonyms = excluded.antonyms;

