  ('de-48', 'success', 'успех', 'табыс', 'the accomplishment of an aim or purpose', 'Consistency and dedication are the true secrets behind language learning success.', '/səkˈses/', 'Noun', 'A2', 'daily-english', array['achievement', 'triumph', 'prosperity', 'victory']::text[], array['failure']::text[]),
