  ('it-21', 'repository', 'репозиторий', 'репозиторий', 'a central storage location where code, commits, and version history are stored', 'Clone the Git repository to your local machine before starting the development server.', '/rɪˈpɒz.ɪ.tər.i/', 'Noun', 'B1', 'it-programming', array['codebase', 'storage', 'archive']::text[], array[]::text[]),
  ('it-22', 'dependency', 'зависимость', 'тәуелділік', 'an external library, module, or package required by a software application to function', 'Update the project dependencies using npm to patch critical security issues.', '/dɪˈpen.dən.si/', 'Noun', 'B1', 'it-programming', array['package', 'module', 'library', 'reliance']::text[], array['independence']::text[]),
  ('it-23', 'parameter', 'параметр', 'параметр', 'a variable in a function definition that receives a value passed during a function call', 'This helper function accepts two parameters: the input text and the target language.', '/pəˈræm.ɪ.tər/', 'Noun', 'B1', 'it-programming', array['argument', 'variable', 'criterion']::text[], array[]::text[]),
