  ('it-25', 'bandwidth', 'пропускная способность', 'өткізу қабілеті', 'the maximum amount of data transmitted over an internet connection in a given time', 'Video streaming consumes considerably more network bandwidth than textual requests.', '/ˈbænd.wɪtθ/', 'Noun', 'B2', 'it-programming', array['capacity', 'throughput', 'data rate']::text[], array[]::text[]),
  ('it-26', 'concurrency', 'параллелизм, конкурентность', 'параллельдік', 'the ability of different parts or units of a program to be executed out-of-order or in partial order', 'Go and Elixir are renowned for their lightweight concurrency primitives.', '/kənˈkʌr.ən.si/', 'Noun', 'C1', 'it-programming', array['parallelism', 'simultaneity', 'multitasking']::text[], array['sequentiality']::text[]),
