  ('it-28', 'endpoint', 'конечная точка API', 'соңғы нүкте', 'a specific URL location where an API receives requests about a specific resource', 'The client sends a POST request to the authentication endpoint with credentials.', '/ˈend.pɔɪnt/', 'Noun', 'B1', 'it-programming', array['API route', 'URL', 'destination']::text[], array[]::text[]),
  ('it-29', 'latency', 'задержка', 'кідіріс', 'the delay before a transfer of data begins following an instruction for its transfer', 'Placing edge servers closer to users drastically decreases round-trip latency.', '/ˈleɪ.tən.si/', 'Noun', 'B2', 'it-programming', array['delay', 'lag', 'response time']::text[], array['speed', 'rapidity']::text[]),
  ('it-30', 'scalable', 'масштабируемый', 'масштабталатын', 'able to be changed in size or scale to accommodate heavy workloads', 'Building stateless services makes the web architecture effortlessly scalable.', '/ˈskeɪ.lə.bəl/', 'Adjective', 'B2', 'it-programming', array['expandable', 'extensible', 'adaptable']::text[], array['rigid', 'unscalable']::text[]),
  ('it-31', 'redundancy', 'избыточность, резервирование', 'резервтеу', 'the inclusion of extra components which are not strictly necessary to function, in case of failure', 'Data centers replicate databases across multiple continents for high hardware redundancy.', '/rɪˈdʌn.dən.si/', 'Noun', 'B2', 'it-programming', array['duplication', 'backup', 'safeguard']::text[], array['scarcity']::text[]),
  ('it-32', 'vulnerability', 'уязвимость', 'осалдық', 'a flaw or weakness in software that can be exploited by an attacker to cause harm', 'A routine automated security scan detected a critical SQL injection vulnerability.', '/ˌvʌl.nər.əˈbɪl.ə.ti/', 'Noun', 'B2', 'it-programming', array['weakness', 'flaw', 'exploit', 'security hole']::text[], array['security', 'invulnerability']::text[]),
  ('it-33', 'encryption', 'шифрование', 'шифрлау', 'the process of converting information or data into a secure code to prevent unauthorized access', 'End-to-end encryption ensures that only the sender and recipient can read the messages.', '/ɪnˈkrɪp.ʃən/', 'Noun', 'B2', 'it-programming', array['ciphering', 'encoding', 'cryptography']::text[], array['decryption', 'plaintext']::text[]),
