  ('it-38', 'benchmark', 'эталонный тест, бенчмарк', 'эталондық сынақ', 'a standard test or of point of reference against which things may be compared or assessed', 'The engineers ran an intensive benchmark to compare Rust and Node.js execution speeds.', '/ˈbentʃ.mɑːk/', 'Noun', 'B2', 'it-programming', array['standard', 'gauge', 'reference point', 'test']::text[], array[]::text[]),
  ('it-39', 'deprecated', 'устаревший (в коде)', 'ескірген', 'declared obsolete and recommended against, while still functioning for backwards compatibility', 'This React lifecycle method has been deprecated in favor of useEffect hooks.', '/ˈdep.rə.keɪ.tɪd/', 'Adjective', 'B2', 'it-programming', array['obsolete', 'outdated', 'disapproved']::text[], array['current', 'recommended']::text[]),
