  ('it-41', 'abstraction', 'абстракция', 'абстракция', 'the quality of dealing with ideas rather than events; hiding internal complexity behind an interface', 'A well-designed API provides a clear abstraction over complex database queries.', '/æbˈstræk.ʃən/', 'Noun', 'B2', 'it-programming', array['generalization', 'concept', 'encapsulation']::text[], array['concrete implementation']::text[]),
  ('it-42', 'polymorphism', 'полиморфизм', 'полиморфизм', 'the condition of occurring in several different forms; methods with the same name doing different things', 'Object-oriented polymorphism allows different shapes to implement their own render method.', '/ˌpɒl.iˈmɔː.fɪ.zəm/', 'Noun', 'C1', 'it-programming', array['multiformity', 'variability']::text[], array['monomorphism']::text[]),
  ('it-43', 'inheritance', 'наследование', 'мұрагерлік', 'the mechanism of basing an object or class upon another object or class', 'TypeScript supports single class inheritance using the extends keyword.', '/ɪnˈher.ɪ.təns/', 'Noun', 'B2', 'it-programming', array['derivation', 'subclassing']::text[], array[]::text[]),
  ('it-44', 'microservices', 'микросервисы', 'микросервистер', 'an architectural approach where an application is arranged as a collection of loosely coupled services', 'Migrating the monolith into cloud-native microservices increased release velocity.', '/ˈmaɪ.krəʊˌsɜː.vɪ.sɪz/', 'Noun', 'B2', 'it-programming', array['distributed services', 'modular architecture']::text[], array['monolith']::text[]),
  ('it-45', 'container', 'контейнер', 'контейнер', 'a standard unit of software that packages up code and all its dependencies so the app runs quickly', 'Docker packages your Next.js application into a lightweight, standalone container.', '/kənˈteɪ.nər/', 'Noun', 'B1', 'it-programming', array['sandbox', 'instance', 'virtual environment']::text[], array[]::text[]),
  ('it-46', 'pipeline', 'конвейер, пайплайн', 'конвейер', 'a set of automated processes that allow developers to compile, build, test, and deploy code', 'The CI/CD pipeline runs unit tests and automated lint checks on every pull request.', '/ˈpaɪp.laɪn/', 'Noun', 'B2', 'it-programming', array['workflow', 'automation chain', 'process']::text[], array[]::text[]),
  ('it-47', 'telemetry', 'телеметрия', 'телеметрия', 'the automatic recording and transmission of operational data from remote or inaccessible sources', 'Application telemetry helps identify performance bottlenecks and crash frequencies in production.', '/təˈlem.ə.tri/', 'Noun', 'C1', 'it-programming', array['analytics', 'monitoring', 'metrics']::text[], array[]::text[]),
  ('it-48', 'refactor', 'рефакторить, перерабатывать код', 'қайта құру', 'restructure existing computer code without changing its external behavior', 'We need to refactor this complex component to improve readability and maintainability.', '/riːˈfæk.tər/', 'Verb', 'B2', 'it-programming', array['restructure', 'clean up', 'optimize', 'reorganize']::text[], array[]::text[]),
  ('it-49', 'schema', 'схема данных', 'деректер сұлбасы', 'the structure of a database system described in a formal language supported by DBMS', 'The Supabase schema defines all database tables, columns, indexes, and RLS policies.', '/ˈskiː.mə/', 'Noun', 'B1', 'it-programming', array['structure', 'blueprint', 'diagram', 'layout']::text[], array[]::text[]),
  ('it-50', 'token', 'токен', 'токен', 'a piece of data that serves as a temporary identifier or security credential', 'Store the authentication token securely in an HTTP-only cookie to prevent XSS attacks.', '/ˈtəʊ.kən/', 'Noun', 'B1', 'it-programming', array['credential', 'symbol', 'badge', 'identifier']::text[], array[]::text[]),
  ('ielts-21', 'ubiquitous', 'вездесущий', 'барлық жерде кездесетін', 'present, appearing, or found everywhere', 'Smartphones have become ubiquitous across modern urban societies.', '/juːˈbɪk.wɪ.təs/', 'Adjective', 'C1', 'ielts', array['omnipresent', 'pervasive', 'universal', 'widespread']::text[], array['rare', 'scarce']::text[]),
  ('ielts-22', 'pragmatic', 'прагматичный', 'практикалық', 'dealing with things sensibly and realistically in a way based on practical rather than theoretical considerations', 'The government adopted a pragmatic approach to environmental regulation and economic growth.', '/præɡˈmæt.ɪk/', 'Adjective', 'B2', 'ielts', array['practical', 'sensible', 'down-to-earth', 'realistic']::text[], array['idealistic', 'impractical']::text[]),
  ('ielts-23', 'exponential', 'экспоненциальный', 'экспоненциалды', 'becoming more and more rapid; exhibiting very high growth rates', 'Technological innovation has experienced exponential acceleration over the past decade.', '/ˌek.spəˈnen.ʃəl/', 'Adjective', 'C1', 'ielts', array['rapid', 'prodigious', 'manifold', 'surging']::text[], array['linear', 'stagnant']::text[]),
  ('ielts-24', 'dichotomy', 'дихотомия', 'дихотомия', 'a division or contrast between two things that are represented as being entirely different', 'The essay explores the rigid dichotomy between urban development and environmental conservation.', '/daɪˈkɒt.ə.mi/', 'Noun', 'C1', 'ielts', array['division', 'split', 'contrast', 'polarization']::text[], array['harmony', 'unity']::text[]),
  ('ielts-25', 'ephemeral', 'мимолетный, эфемерный', 'өткінші', 'lasting for a very short time', 'Fame in the social media era is often ephemeral, fading within weeks.', '/ɪˈfem.ər.əl/', 'Adjective', 'C1', 'ielts', array['transient', 'fleeting', 'short-lived', 'momentary']::text[], array['permanent', 'eternal']::text[]),
  ('ielts-26', 'catalyst', 'катализатор', 'катализатор', 'a person or thing that precipitates an event or accelerates change', 'The introduction of remote learning acted as a powerful catalyst for educational digitalization.', '/ˈkæt.əl.ɪst/', 'Noun', 'B2', 'ielts', array['stimulus', 'spark', 'impetus', 'driver']::text[], array['hindrance']::text[]),
  ('ielts-27', 'paradox', 'парадокс', 'парадокс', 'a seemingly absurd or self-contradictory statement that when investigated may prove to be well founded', 'It is an intriguing paradox that greater connectivity can sometimes lead to increased loneliness.', '/ˈpær.ə.dɒks/', 'Noun', 'B2', 'ielts', array['contradiction', 'anomaly', 'enigma', 'puzzle']::text[], array[]::text[]),
  ('ielts-28', 'profound', 'глубокий, основательный', 'терең', 'very great or intense; having or showing great knowledge or insight', 'The scientific discovery had a profound impact on medical treatments worldwide.', '/prəˈfaʊnd/', 'Adjective', 'B2', 'ielts', array['deep', 'immense', 'insightful', 'fundamental']::text[], array['superficial', 'shallow']::text[]),
  ('ielts-29', 'superficial', 'поверхностный', 'үстірт', 'existing or occurring at or on the surface; not thorough or deep', 'A superficial understanding of grammar is insufficient for scoring Band 8 on the IELTS.', '/ˌsuː.pəˈfɪʃ.əl/', 'Adjective', 'B2', 'ielts', array['shallow', 'surface', 'cursory', 'trivial']::text[], array['profound', 'thorough']::text[]),
  ('ielts-30', 'resilience', 'стойкость, жизнестойкость', 'төзімділік', 'the capacity to withstand or recover quickly from difficulties; toughness', 'Psychological resilience enables individuals to overcome severe professional adversity.', '/rɪˈzɪl.jəns/', 'Noun', 'B2', 'ielts', array['toughness', 'fortitude', 'durability', 'adaptability']::text[], array['fragility', 'vulnerability']::text[]),
  ('ielts-32', 'conundrum', 'головоломка, дилемма', 'жұмбақ', 'a confusing and difficult problem or question', 'Balancing economic expansion with carbon reduction poses an intricate ethical conundrum.', '/kəˈnʌn.drəm/', 'Noun', 'C1', 'ielts', array['dilemma', 'quandary', 'puzzle', 'riddle']::text[], array['solution']::text[]),
  ('ielts-33', 'exemplify', 'служить примером', 'үлгі болу', 'be a typical example of; illustrate by giving an example', 'His rapid progress exemplifies the efficacy of consistent daily retrieval practice.', '/ɪɡˈzem.plɪ.faɪ/', 'Verb', 'B2', 'ielts', array['illustrate', 'epitomize', 'embody', 'demonstrate']::text[], array[]::text[])
